# Lesson 3.4: editing tags (strong, em, hr, br) and the span tag
L = lambda *a: '\n'.join(a)
def P(title, story, code, dis): return (title, story, code, dis)
P34 = [
 P('Bold and italic words', 'Write a paragraph that says This is important text. with the word important in bold using strong. Then write a paragraph that says I love this song. with the word love in italics using em.',
   L('<p>This is <strong>important</strong> text.</p>', '<p>I <em>love</em> this song.</p>'),
   [(0, '<p>This is <strong>important</em> text.</p>'), (1, '<p>I <em>love<em> this song.</p>'), (0, '<p>This is <strong>important text.</p>')]),
 P('A line across the page', 'Write a heading that says Appetizers, then draw a horizontal line under it, then add a paragraph that says Fries.',
   L('<h2>Appetizers</h2>', '<hr>', '<p>Fries</p>'),
   [(1, '<hr></hr>'), (1, '</hr>'), (1, '<hr')]),
 P('A line break in a poem', 'Write one paragraph with two lines of a poem. The first line is Roses are red, and the second line is Violets are blue. Break the line between them with br.',
   L('<p>Roses are red,<br>Violets are blue.</p>'),
   [(0, '<p>Roses are red,<br></br>Violets are blue.</p>'), (0, '<p>Roses are red, Violets are blue.</p>'), (0, '<p>Roses are red,</br>Violets are blue.</p>')]),
 P('Color one word with span', 'Write a paragraph that says My favorite color is tomato. Wrap only the word tomato in a span and color it tomato.',
   L('<p>My favorite color is <span style="color: tomato;">tomato</span>.</p>'),
   [(0, '<p>My favorite color is <span style="color: tomato;">tomato</p>.</span>'), (0, '<p>My favorite color is <span>tomato</span>.</p>'), (0, '<p style="color: tomato;">My favorite color is tomato.</p>')]),
 P('Bold, italic and a break together', 'Write a paragraph with the bold word Warning first, then a line break, then the italic words Slippery floor.',
   L('<p><strong>Warning</strong><br><em>Slippery floor.</em></p>'),
   [(0, '<p><strong>Warning</strong></br><em>Slippery floor.</em></p>'), (0, '<p><strong>Warning<br></strong><em>Slippery floor.</em></p>'), (0, '<p><em>Warning</em><br><strong>Slippery floor.</strong></p>')]),
 P('Separate two sections with a line', 'Build a menu. Write the heading Soups, a paragraph that says Tomato or corn., a horizontal line, the heading Salads, and a paragraph that says Green and crisp.',
   L('<h2>Soups</h2>', '<p>Tomato or corn.</p>', '<hr>', '<h2>Salads</h2>', '<p>Green and crisp.</p>'),
   [(2, '<hr></hr>'), (3, '<h2>Salads</h1>'), (4, '<p>Green and crisp.</p></hr>')]),
 P('Two spans in one sentence', 'Write a paragraph that says Roses are red and violets are blue. Wrap the word red in a span that colors it red, and the word blue in a span that colors it blue.',
   L('<p>Roses are <span style="color: red;">red</span> and violets are <span style="color: blue;">blue</span>.</p>'),
   [(0, '<p>Roses are <span style="color: red;">red</span> and violets are <span style="color: blue;">blue</p></span>.'), (0, '<p>Roses are <span style="color: red;">red</span> and violets are <span style="background-color: blue;">blue</span>.</p>'), (0, '<p>Roses are <span style="color: red">red</span> and violets are <span style="color: blue;">blue</span>.</p style="color: red;">')]),
 P('A recipe line with bold names', 'Write a heading that says Pancakes. Then write a paragraph with the bold word Flour, a line break, and the bold word Eggs. Then a horizontal line.',
   L('<h1>Pancakes</h1>', '<p><strong>Flour</strong><br><strong>Eggs</strong></p>', '<hr>'),
   [(1, '<p><strong>Flour</strong><br><strong>Eggs</p></strong>'), (1, '<p><b>Flour</b><br><strong>Eggs</strong></p>'), (2, '<hr></hr>')]),
 P('A styled full page', 'Build a full page titled Song Review. The body has a heading Song Review, then a paragraph that says I really love this song. with love in italics and really in bold, then a horizontal line, then a paragraph Rating: 5 stars where 5 stars is a gold span.',
   L('<!DOCTYPE html>', '<html>', '<head>', '<title>Song Review</title>', '</head>', '<body>', '<h1>Song Review</h1>', '<p>I <strong>really</strong> <em>love</em> this song.</p>', '<hr>', '<p>Rating: <span style="color: gold;">5 stars</span></p>', '</body>', '</html>'),
   [(7, '<p>I <strong>really</strong> <em>love</strong> this song.</p>'), (8, '<hr></hr>'), (9, '<p>Rating: <span style="color: gold;">5 stars</p></span>')]),
 P('A poem page', 'Build a full page titled Poem. The body has a heading Poem, a paragraph with the two lines Roses are red, and Violets are blue. split by a line break, a horizontal line, and a paragraph that says By me. in italics with em around the whole sentence.',
   L('<!DOCTYPE html>', '<html>', '<head>', '<title>Poem</title>', '</head>', '<body>', '<h1>Poem</h1>', '<p>Roses are red,<br>Violets are blue.</p>', '<hr>', '<p><em>By me.</em></p>', '</body>', '</html>'),
   [(7, '<p>Roses are red,<br></br>Violets are blue.</p>'), (8, '<hr'), (9, '<p><em>By me.</p></em>')]),
]
